/** Returns the value for a box-shadow definition based on elevation token info */
export function createElevationBoxShadowValue(
  primarySpread: string,
  primaryColor: string,
  secondarySpread: string,
  secondaryColor: string,
): string {
  return `${primarySpread} ${primaryColor}, ${secondarySpread} ${secondaryColor}`;
}

/** Returns a the value for a filter: drop-shadow definition based on elevation token info */
export function createElevationFilterValue(
  primarySpread: string,
  primaryColor: string,
  secondarySpread: string,
  secondaryColor: string,
): string {
  return `drop-shadow(${primarySpread} ${primaryColor}) drop-shadow(${secondarySpread} ${secondaryColor})`;
}
